mapper.select:
SELECT arr.id, arr.document_type, arr.scope_team_id, scope_team.name AS scope_team_name, arr.requester_level, arr.step_order, arr.approver_type, arr.approver_user_id, u.name AS approver_name, arr.approver_team_id, approver_team.name AS approver_team_name, arr.receiver_team_id, receiver.name AS receiver_team_name, arr.active FROM approval_route_rules arr LEFT JOIN teams scope_team ON scope_team.id = arr.scope_team_id LEFT JOIN users u ON u.id = arr.approver_user_id LEFT JOIN teams approver_team ON approver_team.id = arr.approver_team_id LEFT JOIN teams receiver ON receiver.id = arr.receiver_team_id WHERE arr.document_type = #{documentType} AND arr.requester_level = #{requesterLevel}
AND arr.scope_team_id IS NULL
AND arr.scope_team_id = #{scopeTeamId}
ORDER BY arr.step_order, arr.id

SELECT id FROM approval_route_rules
WHERE document_type = #{documentType}
  AND requester_level = #{requesterLevel}


      AND scope_team_id IS NULL


      AND scope_team_id = #{scopeTeamId}


  AND step_order = #{stepOrder}
LIMIT 1

mapper.delete:
DELETE FROM approval_document_receivers
WHERE document_type = #{documentType}
  AND document_id = #{documentId}

mapper.update:
UPDATE approval_document_snapshots
SET stored_filename = #{storedFilename},
    original_filename = #{originalFilename},
    content_type = #{contentType},
    file_size = #{fileSize}
WHERE id = #{id}

UPDATE approval_document_snapshots
SET snapshot_html = #{snapshotHtml}
WHERE id = #{id}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM approval_document_receivers
    WHERE document_type = #{documentType}
      AND document_id = #{documentId}
      AND receiver_team_id = #{teamId}
)

